import {parseMeters} from './buildings.mjs';
export function sceneManifest({bounds,side,downloadedAt,grid,terrainMode,records=[],counts={},errors=0,clipped=0,overrides=new Map(),id,resolve}){
return {type:'AtlasSceneManifest',version:1,createdAt:new Date().toISOString(),downloadedAt,units:'metres',selection:{bounds,boundsOrder:'south,west,north,east',sideMetres:side},coordinates:{horizontal:'Local approximate longitude/latitude mapping; X east, Z south; origin at selection centre',verticalZero:terrainMode==='flat'?null:grid?.min??null,verticalZeroDescription:terrainMode==='flat'?'Arbitrary flat ground at zero; no elevation datum':'Minimum sampled DEM elevation subtracted from all scene heights; not a surveyed project datum'},sources:{objects:'OpenStreetMap, ODbL; values not independently surveyed',terrain:'AWS Open Data Terrain Tiles / Mapzen Terrarium; z13, sampled grid',terrainSamplesPerSide:grid?grid.N+1:null},terrainMode,geometry:{...counts,errors,clipped},buildings:records.map(r=>{const f=r.f,key=id(f),o=overrides.get(key)||{},m=r.model||resolve(f),p=f.properties||{};const classification=o.height!==undefined?'user_estimate':m.height===null?'unavailable':parseMeters(p.height)>0?'source_attribute':m.source?.startsWith('Оценка:')?'derived_from_levels':'assumed';return {id:key,name:p.name||null,heightMetres:m.height,minimumHeightMetres:m.minHeight,heightClassification:classification,sourceDescription:m.source,warnings:m.warnings||[],reason:m.reason||null,geometryType:'procedural_extrusion',independentlyVerified:false,photo:o.source?{source:o.source,credit:o.credit||null,side:(o.edge||0)+1,scale:o.photoScale||null,imageIncluded:false}:null};}),limitations:['Source attributes are not independently verified measurements.','Derived and assumed heights are not measured dimensions.','Terrain and building pads are illustrative; not a survey.','Manifest describes the last successfully built scene; textures are not embedded.']};}

